{"l":12,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå til sidst: 'Hvor bor du'?","o":["spørgsmålstegn","punktum","udråbstegn","komma"],"a":"spørgsmålstegn","r":"Sætningen spørger om noget, og 'hvor' er et spørgeord. Et spørgsmål slutter med spørgsmålstegn."},
{"l":31,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Danmark er et lille ___ i Europa.'","o":["lann","land","landt","lannd"],"a":"land","r":"Ordet ender på et stumt d ligesom 'hund' og 'mand'. Der skal ikke noget t med."},
{"l":49,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'grine'?","o":["græde","gabe","le","nyse"],"a":"le","r":"At le og at grine er to ord for det samme. Man gør det, når noget er sjovt."},
{"l":71,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Der er mere end én bil. Hvilken form passer: 'Der holder tre ___ på vejen.'","o":["bil","bilen","bilerne","biler"],"a":"biler","r":"Efter 'tre' skal navneordet stå i flertal: en bil, tre biler. 'Bilerne' bruger man om nogle bestemte biler."},
{"l":89,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: '___ hedder din lærer?'","o":["hvad","hvat","hvadd","hwad"],"a":"hvad","r":"Spørgeord begynder tit med hv, og h'et er stumt. Til sidst står et blødt d."},
{"l":109,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad laver en bager?","o":["biler og busser","brød og kager","huse og skure","sko og støvler"],"a":"brød og kager","r":"En bager bager brød og kager. Du kan høre det på ordet, der kommer af 'at bage'."},
{"l":131,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er stavet rigtigt? Mange voksne drikker det varmt om morgenen.","o":["kafe","kaffi","kaffe","kaffæ"],"a":"kaffe","r":"A'et er kort, så der skal to f'er. Ordet slutter på e."},
{"l":149,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer, når det sker nu: 'Alma ___ en bog lige nu.'","o":["læse","læst","læsning","læser"],"a":"læser","r":"Det sker lige nu, så udsagnsordet står i nutid. Nutid ender her på -r: Alma læser."},
{"l":170,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilket ord rimer på 'hus'?","o":["mus","hest","hat","hund"],"a":"mus","r":"To ord rimer, når de lyder ens til sidst. Hus og mus slutter begge på lyden -us."},
{"l":188,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Vi har en kat. ___ er sort.'","o":["Kat","Katten","Katte","Kattene"],"a":"Katten","r":"Vi ved allerede, hvilken kat det handler om, så ordet står i bestemt form: katten."},
{"l":207,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord bruger man, når ens mave trænger til mad?","o":["tørstig","søvnig","sulten","mæt"],"a":"sulten","r":"Når man trænger til mad, er man sulten. Tørstig er man, når man trænger til noget at drikke."},
{"l":229,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man ungen fra en høne?","o":["ælling","kalv","hvalp","kylling"],"a":"kylling","r":"En høne får kyllinger. En ælling er derimod en andeunge."},
{"l":248,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ella maler et billede af sin kanin. Kaninen er hvid med sorte ører. Billedet skal hænge i køkkenet.' Hvor skal billedet hænge?","o":["I køkkenet","I klassen","I gangen","På hendes værelse"],"a":"I køkkenet","r":"Den sidste sætning fortæller, at billedet skal hænge i køkkenet."},
{"l":267,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvem er din mormor?","o":["din fars mor","din mors mor","din mors søster","din fars søster"],"a":"din mors mor","r":"Ordet viser det selv: mor-mor er mors mor. Din fars mor er din farmor."},
{"l":289,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'tung'? Tænk på en stor sten og en fjer.","o":["lang","blød","let","mørk"],"a":"let","r":"En stor sten er tung, og en fjer er let. Ordene er modsætninger."},
{"l":309,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Svalen bygger sin rede af mudder. Reden sidder tit under et tag. Dér er ungerne i ly for regnen.' Hvorfor sidder reden under et tag?","o":["Fordi mudderet tørrer bedst dér","Fordi svalen skal have skygge om dagen","Fordi svalen ikke kan flyve højt","Fordi ungerne skal være i ly for regnen"],"a":"Fordi ungerne skal være i ly for regnen","r":"Den sidste sætning forklarer det: Under taget er ungerne i ly for regnen."},
{"l":327,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Myre, bi og flue hører sammen. Hvad er de alle sammen?","o":["insekter","fugle","krybdyr","fisk"],"a":"insekter","r":"Insekter er små dyr med seks ben. Myrer, bier og fluer er insekter."},
{"l":348,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Find ordet, der skal skrives med stort: 'Min mormor bor i odense med sin kat.'","o":["mormor","odense","bor","kat"],"a":"odense","r":"Odense er navnet på en by, og bynavne skrives med stort bogstav."},
{"l":370,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad passer, når det skete i går: 'I går ___ vi i svømmehallen.'","o":["bader","bade","badede","badet"],"a":"badede","r":"'I går' viser, at det er sket, så udsagnsordet skal stå i datid: badede."},
{"l":389,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Honning smager meget ___.'","o":["søt","søj","sødd","sød"],"a":"sød","r":"Ordet ender på blødt d og skrives med ét d."},
{"l":409,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Der er flere heste. Vælg rigtigt: 'Vi så nogle ___ heste.'","o":["vilde","vild","vildt","vildskab"],"a":"vilde","r":"Tillægsordet følger navneordet. Der er flere heste, så det får -e: vilde heste."},
{"l":430,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rosa går med sin mormor i haven. De plukker jordbær og lægger dem i en skål. De fleste kommer aldrig ind i køkkenet, for Rosa spiser dem på vejen.' Hvad sker der med de fleste jordbær?","o":["Mormor koger dem","Rosa spiser dem","De bliver til kage","De falder på jorden"],"a":"Rosa spiser dem","r":"Teksten forklarer, at de fleste ikke når ind i køkkenet, fordi Rosa spiser dem på vejen."},
{"l":447,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Viggo hældte vand i en skål og satte den i fryseren. Næste morgen kunne han vende skålen på hovedet, uden at der kom noget ud.' Hvorfor kom der ikke noget ud?","o":["Fordi skålen var utæt","Fordi Viggo havde drukket vandet","Fordi vandet var blevet til is","Fordi nogen havde tømt skålen"],"a":"Fordi vandet var blevet til is","r":"Vand fryser til is i fryseren. Is er fast, så det løber ikke ud af skålen."},
{"l":468,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Jeg bor på birkevej i Vejle.'?","o":["bor","på","i","birkevej"],"a":"birkevej","r":"Birkevej er navnet på en bestemt vej. Vejnavne skrives med stort bogstav."},
{"l":489,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det banker i brystet og pumper blodet rundt. Hvordan staves det?","o":["hjerte","jerte","hjærte","hjerrte"],"a":"hjerte","r":"Ordet begynder med hj og skrives med e, selvom det lyder som æ."},
{"l":508,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver aften læser far en historie for Ellen. Ellen vælger selv bogen. I aften vil hun høre om en drage.' Hvem vælger bogen?","o":["Far","Ellen","Mor","Dragen"],"a":"Ellen","r":"Den anden sætning siger, at Ellen selv vælger bogen. Far læser højt."},
{"l":529,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket tillægsord er lavet af navneordet 'fare'?","o":["farvet","fattig","farlig","fast"],"a":"farlig","r":"Noget, der kan være en fare for os, er farligt. Farvet kommer af 'farve', ikke af 'fare'."},
{"l":547,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? '___ starter filmen?'","o":["vornår","hvornor","hvonår","hvornår"],"a":"hvornår","r":"Ordet består af 'hvor' og 'når'. Derfor står der først o og siden å."},
{"l":567,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kan du slå op i en ordbog?","o":["hvad et ord betyder","hvad klokken er","hvordan vejret bliver","hvor langt der er til månen"],"a":"hvad et ord betyder","r":"En ordbog er en bog om ord. Her kan man finde ordenes betydning og stavemåde."},
{"l":589,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Liva vandt løbet og smilede hele vejen hjem. Hun var ___ af sig selv.'","o":["bange","stolt","sulten","tørstig"],"a":"stolt","r":"Man er stolt, når man er glad for noget, man selv har klaret godt."},
{"l":606,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den lyser op i stuen, når du tænder for den. Hvilken stavemåde er rigtig?","o":["lambe","lamppe","lampe","lampa"],"a":"lampe","r":"Efter m skrives p, selvom det lyder lidt blødt. Der skal kun ét p."},
{"l":629,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Daniel lagde sin tegning i skraldespanden. Læreren tog den op igen og sagde, at den var flot. Da smilede Daniel lidt.' Hvad synes Daniel nok først om sin tegning?","o":["At den er flot","At den er for stor","At læreren skal have den","At den ikke er god nok"],"a":"At den ikke er god nok","r":"Man smider ikke noget ud, som man er tilfreds med. Han troede altså ikke, at tegningen var god."},
{"l":647,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klokken ringede ind. Jens blev stående ved hegnet. Han havde ikke lavet sine lektier og ville helst ikke ind.' Hvorfor ville Jens ikke ind?","o":["Han havde ikke lavet lektier","Han ville spille mere bold","Han havde ikke hørt klokken","Han ventede på sin mor"],"a":"Han havde ikke lavet lektier","r":"Den sidste sætning forklarer, at lektierne ikke var lavet. Derfor har han ikke lyst til at gå ind."},
{"l":669,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad bliver tillægsordet 'lille' til i flertal: 'en lille kanin, to ___ kaniner'?","o":["lille","små","lidt","mindst"],"a":"små","r":"'Lille' skifter helt ord i flertal: en lille kanin, to små kaniner."},
{"l":687,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'sove som en sten'?","o":["at sove på noget hårdt","at sove udenfor","at sove meget dybt","at sove om dagen"],"a":"at sove meget dybt","r":"En sten rører sig ikke. Den, der sover som en sten, sover så tungt, at næsten intet kan vække en."},
{"l":708,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'hvide' i sætningen: 'Min hvide kanin hedder Snefnug.'","o":["navneord","udsagnsord","stedord","tillægsord"],"a":"tillægsord","r":"Ordet fortæller, hvordan kaninen ser ud. Det gør tillægsord."},
{"l":731,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du har bøger og madpakke i den på vej til skole. Find den rigtige stavemåde.","o":["taske","tasske","tasge","tasce"],"a":"taske","r":"Efter a kommer sk. Der skal kun ét s."},
{"l":747,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'Vi så tre ___ ved søen.'","o":["gås","gæs","gåsen","gæssene"],"a":"gæs","r":"I flertal bliver å til æ: en gås, tre gæs. 'Gæssene' er bestemt form, og den står ikke efter et tal."},
{"l":768,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Månen lyser ikke af sig selv. Den får sit lys fra solen. Det er solens lys, vi ser, når månen skinner om natten.' Hvor kommer månens lys fra?","o":["Fra stjernerne","Fra jorden","Fra solen","Fra månen selv"],"a":"Fra solen","r":"Teksten siger, at månen ikke lyser selv, men får sit lys fra solen."},
{"l":786,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket navneord hedder det samme i ental og flertal? Tænk på dyrene på en bondegård.","o":["ko","hest","gris","får"],"a":"får","r":"Det hedder et får og to får. De andre ændrer sig: køer, heste og grise."},
{"l":807,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord bruger man om det at være syg?","o":["sygdom","sult","søvn","sorg"],"a":"sygdom","r":"Sygdom kommer af 'syg' og endelsen -dom. Mæslinger og influenza er eksempler på sygdomme."},
{"l":828,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Vi spiste fisk___ ris og salat.'?","o":["punktum","komma","kolon","udråbstegn"],"a":"komma","r":"Sætningen opremser tre slags mad. Mellem de første to står der komma, og foran det sidste står 'og'."},
{"l":847,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Amir ___ en historie i sit hæfte nu.'","o":["skrive","skrivver","skriver","skriwer"],"a":"skriver","r":"Sætningen handler om nu, så udsagnsordet ender på -r."},
{"l":867,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Olivia har glædet sig til stranden, men turen bliver aflyst. Hvordan har hun det?","o":["lettet","stolt","mæt","skuffet"],"a":"skuffet","r":"Man bliver skuffet, når noget, man har glædet sig til, ikke sker."},
{"l":889,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør du, når du siger, at du er ked af noget, du har gjort?","o":["undskylder","driller","vinder","pjækker"],"a":"undskylder","r":"Når man undskylder, viser man, at man er ked af det, man har gjort."},
{"l":906,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig: 'Læreren ___, at vi skulle tage vores bøger frem.'","o":["sae","sagde","sadde","sagede"],"a":"sagde","r":"I talesprog hører man hverken g eller d, men ordet skrives med begge. Det er datid af 'sige'."},
{"l":927,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en hemmelighed?","o":["noget, der står skrevet i avisen","noget, som alle i klassen ved","noget, der ikke må fortælles videre","noget, der skete for mange år siden"],"a":"noget, der ikke må fortælles videre","r":"En hemmelighed er noget, kun få kender. Derfor må den ikke fortælles til andre."},
{"l":948,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Læreren sagde___ »Find jeres bøger frem.«'?","o":["punktum","spørgsmålstegn","udråbstegn","kolon"],"a":"kolon","r":"Når man først skriver, hvem der taler, står der kolon lige foran anførselstegnet."},
{"l":967,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Spækhuggeren ligner en stor fisk, men den er en hval. Den skal op til overfladen for at trække vejret.' Hvorfor skal spækhuggeren op til overfladen?","o":["For at trække vejret","For at finde sin mad","For at kigge på både","For at varme sig i solen"],"a":"For at trække vejret","r":"Den sidste sætning siger det direkte. Hvaler har lunger og skal have luft."},
{"l":987,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Peber, kanel og karry giver smag til maden. Hvad er de alle sammen?","o":["mejerivarer","krydderier","drikkevarer","grøntsager"],"a":"krydderier","r":"Krydderier bruger man i små mængder for at give maden mere smag."},
{"l":1007,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find udsagnsleddet: 'Det lille lam står bag hegnet.'","o":["Det lille lam","bag hegnet","står","hegnet"],"a":"står","r":"Udsagnsleddet fortæller, hvad lammet gør. Det står, og du kan sige 'at stå'."},
{"l":1024,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Alfred siger, at han ikke har 'en rød øre'. Hvad betyder det?","o":["at han er kold om ørerne","at han ikke kan høre godt","at han ikke kan lide farven","at han ingen penge har"],"a":"at han ingen penge har","r":"En øre er en meget lille mønt. Har man ikke en rød øre, har man slet ingen penge."},
{"l":1046,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Er det en hel sætning: 'Solen skinner over byen'?","o":["Ja, der er både grundled og udsagnsled","Nej, der mangler et grundled","Nej, der mangler et udsagnsled","Nej, der mangler begge led"],"a":"Ja, der er både grundled og udsagnsled","r":"'Solen' er grundled, og 'skinner' er udsagnsled. Så er der en hel sætning."},
{"l":1068,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning viser rigtigt, hvad Zainab siger om is?","o":["Zainab sagde »: Jeg kan lide is.«","Zainab sagde: »Jeg kan lide is.«","Zainab: sagde »Jeg kan lide is.«","»Zainab sagde: Jeg kan lide is.«"],"a":"Zainab sagde: »Jeg kan lide is.«","r":"Kolon står lige efter 'sagde', og anførselstegnene står kun om de ord, Zainab siger."},
{"l":1089,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? '___ begyndte det at regne.'","o":["plusselig","pludseli","pludselig","plutselig"],"a":"pludselig","r":"Der står et stumt d midt i ordet, og det ender på -lig."},
{"l":1106,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Tobias var lille, var han bange for vand. Nu er han ti år og svømmer på et hold. Hans mor kan næsten ikke tro det.' Hvad har ændret sig for Tobias?","o":["Han er holdt op med at gå til svømning","Hans mor er begyndt at svømme","Han er begyndt at svømme med sin mor","Han er ikke bange for vand mere"],"a":"Han er ikke bange for vand mere","r":"Teksten sætter dengang over for nu: Før var han bange, nu svømmer han på et hold."},
{"l":1124,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Gudenåen er et egennavn. Hvilket fællesnavn passer til det?","o":["å","sø","bjerg","by"],"a":"å","r":"Gudenåen er navnet på én bestemt å. Ordet 'å' er fællesnavnet for alle åer."},
{"l":1147,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den dag på året, hvor du bliver et år ældre. Find den rigtige stavemåde.","o":["fødseldag","fødselsdag","føselsdag","fødsels dag"],"a":"fødselsdag","r":"Ordet skrives i ét ord med et ekstra s i midten. Husk det stumme d i starten."},
{"l":1164,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Da vi kom hjem___ spiste vi kage.'?","o":["punktum","kolon","komma","spørgsmålstegn"],"a":"komma","r":"'Da vi kom hjem' kan ikke stå alene. Det er en ledsætning, og når den står først, skal der komma efter den."},
{"l":1188,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Da det blev mørkt gik vi ind.'?","o":["det","gik","ind","mørkt"],"a":"mørkt","r":"Ledsætningen 'Da det blev mørkt' slutter efter 'mørkt'. Kommaet skiller den fra resten af sætningen."},
{"l":1206,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Grøntsagen, du kan koge, mose eller lave til pommes frites. Hvilket ord er stavet rigtigt?","o":["kartoffel","kartofel","katoffel","kartoffl"],"a":"kartoffel","r":"Ordet skrives med to f'er. Husk r'et i starten og -el til sidst."},
{"l":1227,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Morfar siger, at han kun kan gå langsomt nu. Alligevel er han altid den første, der står klar ved havelågen, når Oscar har fodboldkamp.' Hvad viser teksten?","o":["At morfar er vigtig for Oscars hold","At morfar gerne vil se Oscar spille","At morfar spiller fodbold med Oscar","At morfar er træt af fodbold"],"a":"At morfar gerne vil se Oscar spille","r":"Selv om det er besværligt for ham at gå, står han klar hver gang. Det viser, at han gerne vil med."},
{"l":1245,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Oliver prøvede at lukke kufferten. Han satte sig på den og trykkede. Den ene lynlås gik op igen, og en sok stak ud.' Hvad er problemet?","o":["Kufferten er for tung at løfte","Oliver har glemt sine sokker","Der er for meget i kufferten","Lynlåsen mangler helt"],"a":"Der er for meget i kufferten","r":"Han må sætte sig på kufferten, og den går op igen. Så er den alt for fyldt."},
{"l":1264,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad bruger man en nødudgang til?","o":["at komme ind, hvis man har glemt sin nøgle","at komme op på taget for at se udsigten","at komme ned i kælderen for at hente saft","at komme ud, hvis der sker noget farligt"],"a":"at komme ud, hvis der sker noget farligt","r":"Nød betyder fare. En nødudgang er altså en vej ud, hvis der for eksempel er brand."},
{"l":1287,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordsproget 'Af skade bliver man klog'?","o":["at man lærer noget af sine fejl","at man skal passe på ikke at slå sig","at kloge mennesker aldrig laver fejl","at det er farligt at gå på skolen"],"a":"at man lærer noget af sine fejl","r":"Har man først prøvet, at noget går galt, ved man, hvad man skal gøre anderledes næste gang."},
{"l":1306,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige flertalsform: 'Jeg har fået kolde ___ i sneen.'","o":["føder","fødder","fodder","fødere"],"a":"fødder","r":"Flertal af 'fod' skrives med ø og to d'er. 'Føder' er noget andet, nemlig at give mad."},
{"l":1324,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordsproget 'Stille vand har dyb grund'?","o":["at man aldrig må bade i en sø, når der er stille","at fisk bedst kan lide at svømme på dybt vand","at stille mennesker kan tænke mere, end man tror","at det er farligt at sejle, når der ikke er vind"],"a":"at stille mennesker kan tænke mere, end man tror","r":"Vandet ser roligt ud på overfladen, men kan være dybt. Sådan kan stille mennesker også have meget indeni."},
{"l":1347,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'bide i det sure æble'?","o":["at spise noget, man slet ikke kan lide smagen af","at blive sur på en, der har drillet en i frikvarteret","at plukke æbler, før de er helt modne på træet","at gøre noget kedeligt, man ikke kan slippe for"],"a":"at gøre noget kedeligt, man ikke kan slippe for","r":"Nogle gange må man bare gøre det, der ikke er rart, for eksempel at sige undskyld eller rydde op."},
{"l":1366,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mor åbnede døren og stoppede brat. Gulvet var dækket af mel. Midt i det hele sad hunden Ludo og slikkede sig om munden, og posen lå tom.' Hvem har lavet rodet?","o":["Ludo","Mor","Katten","Far"],"a":"Ludo","r":"Hunden sidder i melet og slikker sig om munden. Den har taget posen."},
{"l":1384,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Efter stormen var taget ___, så det regnede ind.'","o":["usynligt","utæt","uartigt","uvenligt"],"a":"utæt","r":"Noget er utæt, når vand eller luft kan komme igennem. Det er det modsatte af tæt."},
{"l":1406,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Vi sad ___ og spiste.'","o":["samman","sammæn","sammen","sammenn"],"a":"sammen","r":"A'et er kort, så der skal to m'er. Ordet slutter på -en."},
{"l":1428,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om Leo har alle tegn rigtigt?","o":["Da Leo kom hjem sagde, han: »Jeg er hjemme!«","Da Leo, kom hjem sagde han: »Jeg er hjemme!«","Da Leo kom hjem sagde han »: Jeg er hjemme!«","Da Leo kom hjem, sagde han: »Jeg er hjemme!«"],"a":"Da Leo kom hjem, sagde han: »Jeg er hjemme!«","r":"Der skal komma efter ledsætningen 'Da Leo kom hjem' og kolon lige før den direkte tale."},
{"l":1445,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'smal', når vi taler om en vej?","o":["bred","kort","lav","tynd"],"a":"bred","r":"En smal vej har ikke meget plads fra side til side, mens en bred vej har god plads. 'Kort' er det modsatte af 'lang'."},
{"l":1465,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Man har ti ___ på sine hænder.'","o":["finger","fingre","fingeren","fingrene"],"a":"fingre","r":"Efter 'ti' står ubestemt flertal: en finger, ti fingre. E'et i endelsen falder væk."},
{"l":1485,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores hjerte er en muskel. Det pumper blod rundt i hele kroppen. Når vi løber, slår det hurtigere, fordi musklerne skal bruge mere ilt.' Hvorfor slår hjertet hurtigere, når vi løber?","o":["Fordi blodet bliver varmt","Fordi vi bliver bange","Fordi musklerne skal bruge mere ilt","Fordi hjertet bliver større"],"a":"Fordi musklerne skal bruge mere ilt","r":"Den sidste sætning forklarer det: Musklerne skal bruge mere ilt, og blodet bringer ilten ud til dem."},
{"l":1505,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord mangler stort bogstav: 'Søndag besøgte vi mormor i ribe.'?","o":["besøgte","vi","mormor","ribe"],"a":"ribe","r":"Ribe er et bynavn. 'Søndag' har kun stort bogstav, fordi det står først i sætningen."},
{"l":1525,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange punktummer mangler der i teksten: 'Solen skinner Fuglene synger Det er forår'?","o":["tre","to","fire","fem"],"a":"tre","r":"Teksten har tre sætninger, og hver af dem skal slutte med punktum. Også den sidste sætning mangler sit punktum."},
{"l":1547,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Denne fugl er meget ___ og bor kun få steder i verden.'","o":["sjællen","sjælden","sjelden","sjældn"],"a":"sjælden","r":"Ordet skrives med sj, æ og ld. D'et kan næsten ikke høres."},
{"l":1566,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du trækker vejret med den, og den sidder i brystet. Hvilket ord er stavet rigtigt?","o":["lungge","lunnge","lunge","lonnge"],"a":"lunge","r":"Ordet rimer på 'tunge' og skrives også med ng."},
{"l":1585,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Karl købte et viskelæder___ en lineal og et penalhus.'?","o":["kolon","punktum","spørgsmålstegn","komma"],"a":"komma","r":"Karl køber tre ting, og det er en opremsning. Mellem de to første ting skal der stå komma."},
{"l":1605,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Hvornår kommer din kusine fra tyskland?'","o":["tyskland","kommer","din","kusine"],"a":"tyskland","r":"Tyskland er navnet på et land. 'Hvornår' har allerede stort bogstav, fordi det står først."},
{"l":1625,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Vi så en film om nilen i tirsdags.'?","o":["så","nilen","film","tirsdags"],"a":"nilen","r":"Nilen er navnet på en flod, og navne på floder skrives med stort. 'tirsdags' er en ugedag og skrives med lille."},
{"l":1645,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Man skriver først 'Emil sagde' og derefter det, Emil siger. Hvad hedder tegnet, der skal stå imellem?","o":["punktum","udråbstegn","kolon","spørgsmålstegn"],"a":"kolon","r":"Kolon varsler, at nu kommer det, personen siger. Bagefter står ordene i anførselstegn."},
{"l":1665,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lukas ville sælge sin gamle cykel. Han skrev på sedlen, at den kørte som ny. Men køberen fik straks øje på den rustne kæde og det flade dæk.' Hvad er der galt med sedlen?","o":["Der står ikke, hvad cyklen koster","Der står ikke, hvem der sælger den","Der står ikke, hvor cyklen er","Der står noget, som ikke passer"],"a":"Der står noget, som ikke passer","r":"Der stod, at cyklen kørte som ny, men kæden var rusten, og dækket var fladt. Det passer ikke."},
{"l":1685,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort bogstav: 'I påsken var vi på kronborg.'?","o":["kronborg","påsken","var","vi"],"a":"kronborg","r":"Kronborg er navnet på et slot. Højtider som påsken skrives med lille."},
{"l":1705,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om frikvarteret skal slutte med spørgsmålstegn?","o":["Vi skal spille bold i frikvarteret","Hvad skal vi lave i frikvarteret","Frikvarteret er slut om lidt","Jeg sad på bænken i frikvarteret"],"a":"Hvad skal vi lave i frikvarteret","r":"'Hvad' er et spørgeord, og sætningen beder om et svar. De andre sætninger fortæller noget."},
{"l":1727,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Jeg kan ___ finde mine sko.'","o":["ike","igge","ikke","ikkæ"],"a":"ikke","r":"Ordet skrives med to k'er. Det lyder blødt, men der skal ikke g."},
{"l":1746,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Der var ___ blomster i haven.'","o":["smuke","smugge","smukkæ","smukke"],"a":"smukke","r":"I flertal får ordet -e, og derfor bliver k'et dobbelt."},
{"l":1765,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'Vi ___ og spiste på bænken i går.'","o":["sad","sidder","satte","siddet"],"a":"sad","r":"Datid af 'at sidde' er 'sad'. 'Satte' er datid af 'at sætte'."},
{"l":1785,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal efterfølges af komma: 'Når jeg bliver stor vil jeg være dyrlæge.'?","o":["bliver","stor","vil","jeg"],"a":"stor","r":"Ledsætningen 'Når jeg bliver stor' slutter efter 'stor'. Efter en ledsætning, der står først, skal der komma."},
{"l":1805,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Sætningen fortæller roligt om en plan: 'I morgen skal vi på udflugt'. Hvilket tegn skal den slutte med?","o":["spørgsmålstegn","komma","punktum","kolon"],"a":"punktum","r":"Sætningen fortæller noget i et roligt toneleje og spørger ikke. Derfor er punktum det rigtige tegn."},
{"l":1825,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vores nye nabo kommer fra polen og taler polsk.'?","o":["nabo","taler","polsk","polen"],"a":"polen","r":"Polen er navnet på et land. Sproget polsk er ikke et navn og skrives med lille."},
{"l":1845,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvem har taget min blyant? sagde Thea. Hun kiggede rundt. Malte sad med en blyant bag øret og lagde hurtigt sin hånd på den.' Hvad tænker Malte nok?","o":["At Thea ikke må se blyanten","At Thea skal have en ny blyant","At han vil låne blyanten ud til Thea","At hans blyant er den pæneste"],"a":"At Thea ikke må se blyanten","r":"Han skjuler blyanten med hånden, da Thea spørger. Det tyder på, at det er hendes, og at han ikke vil afsløres."},
{"l":1865,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Træneren råbte: »Skyd nu___«'?","o":["kolon","udråbstegn","komma","spørgsmålstegn"],"a":"udråbstegn","r":"Træneren råber en kort besked. Et råb slutter med udråbstegn, og det står inde i anførselstegnene."},
{"l":1885,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Der skal stå punktum ét sted inde i teksten. Efter hvilket ord: 'Vi pakkede bilen Så kørte vi mod Skagen.'?","o":["pakkede","Så","bilen","kørte"],"a":"bilen","r":"Den første sætning er færdig efter 'bilen'. 'Så' har stort bogstav, fordi den næste sætning begynder dér."},
{"l":1908,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Her er et rart ___ at holde ferie.'","o":["stedd","stet","stæd","sted"],"a":"sted","r":"Ordet ender på blødt d og skrives med e."},
{"l":1925,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange kommaer skal der stå i: 'Til festen kom Ali Sara Mads Ella og Jonas.'?","o":["tre","to","fire","fem"],"a":"tre","r":"Der skal komma efter Ali, Sara og Mads. Mellem Ella og Jonas står 'og', så der skal ikke komma dér."},
{"l":1945,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort begyndelsesbogstav: 'Himlen var grå. vinden blæste hårdt.'?","o":["grå","vinden","blæste","hårdt"],"a":"vinden","r":"Efter punktummet begynder en ny sætning, og det første ord i en sætning skal have stort bogstav."},
{"l":1965,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Min lille bror slog sit ___ mod bordet.'","o":["hoed","hovet","hoved","hovved"],"a":"hoved","r":"V'et skal med, selvom det næsten ikke høres. Ordet ender på blødt d."},
{"l":1985,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort, fordi den direkte tale begynder dér: 'Læreren sagde: »find en makker.«'?","o":["sagde","en","makker","find"],"a":"find","r":"Læreren siger en hel sætning, og den skal begynde med stort bogstav, også selv om den står efter et kolon."},
{"l":2005,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vi sejlede over kattegat til Læsø.'?","o":["kattegat","sejlede","over","til"],"a":"kattegat","r":"Kattegat er navnet på et farvand, og geografiske navne skrives med stort."},
{"l":2025,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af at 'forbyde' noget?","o":["at forklare det","at tillade det","at bestemme det","at love det"],"a":"at tillade det","r":"Det, der er forbudt, må man ikke. Det, der er tilladt, må man gerne."},
{"l":2045,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler der komma: 'Selvom det regnede spillede vi videre.'?","o":["det","spillede","regnede","vi"],"a":"regnede","r":"'Selvom det regnede' er en ledsætning, der står først. Hovedsætningen begynder med 'spillede'."},
{"l":2065,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Jeppe er syg. Hvilket ord er rigtigt: 'Jeg afleverer ___ bog til læreren.'","o":["sin","ham","han","hans"],"a":"hans","r":"Grundleddet er 'jeg', og bogen er Jeppes. Så hedder det 'hans' og ikke 'sin'."},
{"l":2085,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vandet i havet varmes op af solen og stiger op som vanddamp. Højt oppe bliver det koldt og danner skyer. Til sidst falder det som regn, og så begynder det hele forfra.' Hvad sker der lige efter, at vanddampen er steget op?","o":["Der dannes skyer","Vandet varmes af solen","Regnen falder","Havet bliver koldt"],"a":"Der dannes skyer","r":"Rækkefølgen er: vand varmes, damp stiger op, skyer dannes, og regn falder."},
{"l":2105,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'I ferien så vi alperne fra toget.'?","o":["ferien","alperne","så","toget"],"a":"alperne","r":"Alperne er navnet på en bjergkæde. Navne på bjerge og bjergkæder skrives med stort."},
{"l":2125,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Jonas spurgte sin far___ »Hvornår spiser vi?«'?","o":["punktum","spørgsmålstegn","kolon","udråbstegn"],"a":"kolon","r":"Kolon står lige foran den direkte tale. Spørgsmålstegnet står allerede inde i anførselstegnene."},
{"l":2145,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en 'trækfugl' om efteråret?","o":["bliver hjemme og fryser","bygger sig en ny rede","graver sig ned i jorden","flyver til varmere lande"],"a":"flyver til varmere lande","r":"Trækfugle som storken og svalen flyver sydpå, fordi de ikke kan finde føde her om vinteren."},
{"l":2165,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Hos Yasmin i Odense holdt vi Fastelavn.'?","o":["Fastelavn","Hos","Yasmin","Odense"],"a":"Fastelavn","r":"Højtider som fastelavn, jul og påske skrives med lille. Yasmin og Odense er navne, og 'Hos' står først."},
{"l":2185,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find bindeordet: 'Ali drikker saft, og Mette spiser en bolle.'","o":["drikker","og","bolle","saft"],"a":"og","r":"Bindeord binder ord eller sætninger sammen. 'Og' binder de to sætninger sammen."},
{"l":2205,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Fordi bussen var forsinket kom vi for sent.'?","o":["bussen","kom","forsinket","vi"],"a":"forsinket","r":"'Fordi bussen var forsinket' er en ledsætning, der står først. Kommaet skiller den fra 'kom vi for sent'."},
{"l":2225,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning viser rigtigt, at Fatima råber efter sin ven?","o":["Fatima råbte: »Kom tilbage?«","Fatima råbte? »Kom tilbage.«","Fatima råbte. »Kom tilbage!«","Fatima råbte: »Kom tilbage!«"],"a":"Fatima råbte: »Kom tilbage!«","r":"Efter 'råbte' står kolon, fordi direkte tale følger. Udråbstegnet hører til råbet og står inde i anførselstegnene."},
{"l":2245,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort bogstav: 'Hver sommer bader vi i vesterhavet.'?","o":["vesterhavet","sommer","bader","vi"],"a":"vesterhavet","r":"Vesterhavet er navnet på et bestemt hav. Årstider som sommer skrives med lille."},
{"l":2265,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket udsagnsord hører til navneordet 'sang'?","o":["svinge","synge","springe","sænke"],"a":"synge","r":"Man synger en sang. Ordene er i familie, selvom vokalen skifter fra y til a."},
{"l":2285,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Mens regnen faldt___ sad vi i teltet.'?","o":["kolon","punktum","komma","udråbstegn"],"a":"komma","r":"'Mens regnen faldt' er en ledsætning og ikke en hel sætning for sig. Derfor skal der komma og ikke punktum."},
{"l":2305,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find udsagnsleddet: 'Hver morgen spiser Jonas havregryn.'","o":["Hver morgen","Jonas","havregryn","spiser"],"a":"spiser","r":"'Spiser' er udsagnsordet og fortæller, hvad Jonas gør hver morgen."},
{"l":2325,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Min onkel arbejder i nordjylland om vinteren.'?","o":["nordjylland","onkel","arbejder","vinteren"],"a":"nordjylland","r":"Nordjylland er navnet på en landsdel. 'nord' skrives med lille alene, men her er det en del af et stednavn."},
{"l":2345,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Personen, der undersøger dig, når du er syg. Vælg den rigtige stavemåde.","o":["læje","læge","læhe","lææge"],"a":"læge","r":"Ordet skrives med æ og ét g, selvom det kan lyde som j."},
{"l":2364,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bjørnen går i hi, når det bliver koldt. Den spiser sig tyk om efteråret, for i hiet spiser den næsten ikke. Om foråret er den meget tyndere.' Hvorfor spiser bjørnen så meget om efteråret?","o":["For at blive stærkere end andre bjørne","For at hjælpe ungerne med at finde mad","For at det kan holde den gennem vinteren","For at få en tykkere pels om vinteren"],"a":"For at det kan holde den gennem vinteren","r":"Bjørnen spiser næsten ikke i hiet, så den må leve af det, den har spist om efteråret."},
{"l":2385,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et 'bevis'?","o":["et spørgsmål, man stiller læreren","en historie, man selv har fundet på","et gæt på, hvad der sker i morgen","noget, der viser, at noget er sandt"],"a":"noget, der viser, at noget er sandt","r":"Et bevis gør det muligt at sige, at noget er sandt. Et fodspor i sneen kan for eksempel bevise, at nogen har gået der."},
{"l":2405,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvem er det, der siger ordene i: '»Theo har lånt min bog«, sagde Aisha.'?","o":["Aisha","Theo","læreren","fortælleren"],"a":"Aisha","r":"Ordene efter anførselstegnene fortæller, hvem der taler: 'sagde Aisha'. Theo bliver kun nævnt i det, hun siger."},
{"l":2424,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Regnskoven kaldes tit for jordens lunger. Træerne optager kuldioxid og sender ilt ud i luften. Når regnskoven fældes, mister vi noget af det, der renser luften.' Hvorfor kaldes regnskoven for jordens lunger?","o":["Fordi den ligner to store lunger","Fordi træerne giver os ilt","Fordi man kan høre den trække vejret","Fordi den vokser meget hurtigt"],"a":"Fordi træerne giver os ilt","r":"Vores lunger hjælper os med ilt. Regnskovens træer sender ilt ud, og derfor bruges ordet som billede."},
{"l":2445,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en, der 'mumler'?","o":["taler højt og klart","synger en glad sang","taler lavt og utydeligt","spiser meget langsomt"],"a":"taler lavt og utydeligt","r":"Når nogen mumler, er det svært at høre ordene, fordi personen næsten ikke åbner munden."},
{"l":2465,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: 'Vi taler Engelsk med Zoe fra London.'?","o":["Vi","Zoe","London","Engelsk"],"a":"Engelsk","r":"På dansk skrives sprog med lille bogstav. På engelsk er det omvendt, og derfor kommer man let til at lave fejlen."},
{"l":2485,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor skal det første komma stå: 'På turen skal du bruge sovepose lommelygte regnjakke og madpakke.'?","o":["efter sovepose","efter lommelygte","efter regnjakke","efter madpakke"],"a":"efter sovepose","r":"Opremsningen begynder med 'sovepose', og det første komma skiller den fra 'lommelygte'."},
{"l":2505,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om børnenes tur er rigtig?","o":["De løb, over vejen ind i skoven og op på bakken.","De løb over vejen, ind i skoven og op på bakken.","De løb over vejen ind, i skoven og op på bakken.","De løb over vejen, ind i skoven, og op på bakken."],"a":"De løb over vejen, ind i skoven og op på bakken.","r":"Her består hver del i opremsningen af flere ord. Kommaet står mellem delene, men ikke foran 'og'."},
{"l":2525,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort, fordi en ny sætning begynder: 'Vi hørte en lyd. det var bare vinden.'?","o":["hørte","lyd","det","vinden"],"a":"det","r":"Efter punktummet begynder en ny sætning, så det første ord skal have stort bogstav."},
{"l":2544,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et kæmpestort dyr, der uddøde for millioner af år siden. Hvordan staves det?","o":["dinosår","dinusaur","dinnosaur","dinosaur"],"a":"dinosaur","r":"Ordet skrives med i og o og slutter på -saur."},
{"l":2565,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Tobias besøgte en Nordmand i Oslo i Norge.'?","o":["Nordmand","Tobias","Oslo","Norge"],"a":"Nordmand","r":"Ord for folk fra et land skrives med lille, for eksempel nordmand og dansker. Landet og byen er navne."},
{"l":2585,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort bogstav: 'Min bedste ven hedder Nora jensen.'?","o":["bedste","jensen","ven","hedder"],"a":"jensen","r":"Efternavne er navne ligesom fornavne. Både Nora og Jensen skal have stort bogstav."},
{"l":2604,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nora var skuffet over at skulle til sin moster på ferie i stedet for til Spanien. Men på vej hjem to uger efter talte hun kun om hestene, om søen og om mosters kager, og hun spurgte, hvornår de skulle derop igen.' Hvad er der sket med Nora?","o":["Hun er stadig skuffet over ferien hos moster","Hun vil hellere til Spanien næste gang","Hun er blevet glad for ferien hos moster","Hun har mistet lysten til at ride på heste"],"a":"Hun er blevet glad for ferien hos moster","r":"Først var hun skuffet, men bagefter taler hun kun om hestene og søen og vil gerne derop igen."},
{"l":2625,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når Mathilde spørger, og 'spurgte Mathilde' står til sidst?","o":["»Hvor skal vi hen« spurgte? Mathilde.","»Hvor skal vi hen.« spurgte Mathilde.","»Hvor skal vi hen?« spurgte. Mathilde.","»Hvor skal vi hen?« spurgte Mathilde."],"a":"»Hvor skal vi hen?« spurgte Mathilde.","r":"Spørgsmålstegnet hører til det, hun spørger om, så det står inde i anførselstegnene. Hele sætningen slutter med punktum efter 'Mathilde'."},
{"l":2645,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange kommaer mangler der i: 'Da vi kom hjem fandt vi nøgler penge og en taske på bordet.'?","o":["to","ét","tre","fire"],"a":"to","r":"Et komma skal stå efter ledsætningen 'Da vi kom hjem', og et andet skal stå efter 'nøgler' i opremsningen."},
{"l":2665,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer til et-ordet 'hus': 'Huset på hjørnet er ___.'","o":["gammel","gammelt","gamle","alder"],"a":"gammelt","r":"Det hedder et hus, så tillægsordet får -t, selv om det står efter 'er'."},
{"l":2685,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Man kan måle et træs alder ved at tælle dets årringe. Hvert år vokser der en ny ring. I gode år med meget regn bliver ringen bred, og i tørre år bliver den smal.' Hvad kan en smal årring fortælle?","o":["At træet er meget ungt","At træet har været sygt i mange år","At det år var tørt","At det år var meget regnfuldt"],"a":"At det år var tørt","r":"Teksten siger, at ringen bliver smal i tørre år. Så kan man aflæse vejret fra dengang."},
{"l":2705,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord indleder ledsætningen: 'Når bussen kommer, stiger vi på.'?","o":["bussen","stiger","vi","Når"],"a":"Når","r":"Ledsætninger begynder ofte med et bindeord som 'når', 'da', 'hvis' eller 'fordi'. Her står det helt først."},
{"l":2725,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du holder den over hovedet, når det regner. Hvordan staves den?","o":["paraply","parraply","paraplu","parapli"],"a":"paraply","r":"Ordet har ét r i midten, og det slutter på y."},
{"l":2745,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler der komma: 'Hvis solen skinner på lørdag tager vi til stranden.'?","o":["skinner","lørdag","tager","vi"],"a":"lørdag","r":"'på lørdag' hører med til ledsætningen. Hovedsætningen begynder først med 'tager', så kommaet står efter 'lørdag'."},
{"l":2765,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om dyrene på gården har ingen overflødige kommaer?","o":["Om morgenen, fodrer vi høns og geder.","Om morgenen fodrer, vi høns og geder.","Om morgenen fodrer vi høns og geder.","Om morgenen fodrer vi høns, og geder."],"a":"Om morgenen fodrer vi høns og geder.","r":"'Om morgenen' er ikke en ledsætning, for der er intet udsagnsord. Og to ting bundet sammen med 'og' skal ikke have komma."},
{"l":2785,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er udsagnsleddet i spørgsmålet: 'Har du husket din madpakke i dag?'","o":["du","din madpakke","i dag","Har husket"],"a":"Har husket","r":"Grundleddet 'du' står mellem de to udsagnsord, men 'har' og 'husket' hører sammen."},
{"l":2805,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Efter at vi havde ryddet op gik vi ud at lege.'?","o":["op","ryddet","gik","ud"],"a":"op","r":"Ledsætningen er 'Efter at vi havde ryddet op'. 'Op' hører med til 'ryddet', så kommaet kommer efter det."},
{"l":2825,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Da toget kørte fra roskilde, var klokken otte om tirsdagen.'?","o":["toget","roskilde","klokken","tirsdagen"],"a":"roskilde","r":"Roskilde er et bynavn og skal have stort bogstav. Ugedage skrives med lille, også i bestemt form."},
{"l":2845,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Ordet 'sang' står to gange i sætningen 'Hun sang en smuk sang.' Hvilke ordklasser er det?","o":["først navneord, så udsagnsord","begge gange udsagnsord","først udsagnsord, så navneord","begge gange navneord"],"a":"først udsagnsord, så navneord","r":"Den første 'sang' fortæller, hvad hun gjorde. Den anden kan få 'en' foran sig."},
{"l":2865,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vores skolerejse går til berlin i september.'?","o":["skolerejse","går","september","berlin"],"a":"berlin","r":"Berlin er en by og skal have stort bogstav. Måneden september skrives med lille."},
{"l":2882,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Jeg ___ om fingrene i dag.'","o":["fryser","frysser","fryse","frøser"],"a":"fryser","r":"Det sker nu, så ordet skal have r til sidst. Y'et er langt, så der er kun ét s."},
{"l":2904,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg det ord, der passer: 'Katten kan ___ i solen i timevis.'","o":["lægge","ligge","ligger","lagde"],"a":"ligge","r":"Katten er i ro og flytter ikke noget. Efter 'kan' står navnemåden af det ord, der betyder at være i ro."},
{"l":2925,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Liva hældte vand i en flaske og satte den i fryseren uden låg. Næste morgen var isen vokset op over kanten. Hun kiggede forundret på flasken og hentede sin bog om vand. Her stod der, at vand fylder mere, når det fryser til is.' Hvad forklarede bogen for Liva?","o":["Hvorfor flasken var blevet koldere end fryseren","Hvorfor vand smager anderledes, når det er frosset","Hvorfor isen var vokset op over flaskens kant","Hvorfor man skal sætte låg på alle sine flasker"],"a":"Hvorfor isen var vokset op over flaskens kant","r":"Bogen siger, at vand fylder mere som is. Det er årsagen til det, Liva undrede sig over."},
{"l":2942,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Oskar 'gik på listesko' ned ad trappen om natten. Hvordan gik han?","o":["Hurtigt og med høje skridt","Med en tung rygsæk på","I sine allernyeste sko","Meget stille og forsigtigt"],"a":"Meget stille og forsigtigt","r":"Listesko er bløde sko, der ikke larmer. Vendingen bruges om at gå eller handle stille, så ingen opdager det."},
{"l":2961,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange fugle flyver sydpå om efteråret. De flyver ikke væk, fordi de fryser. De flyver, fordi insekterne forsvinder, og jorden fryser til, så de ikke kan finde føde. Om foråret, når der igen er mad, vender de hjem.' Hvad er den vigtigste grund til, at fuglene flyver sydpå?","o":["De kan ikke finde mad nok","De kan ikke tåle kulden","De vil væk fra sneen","De skal lære ungerne at flyve"],"a":"De kan ikke finde mad nok","r":"Teksten afviser, at det handler om kulde, og siger, at det er føden, der forsvinder."},
{"l":2981,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt her? 'Jeg vil gerne ___ ved siden af Yusuf i bussen.'","o":["sætte","sidde","sidder","sad"],"a":"sidde","r":"Her handler det om at være et sted, ikke om at flytte noget. Efter 'vil' står navnemåden."},
{"l":3003,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvem handler sætningen om? Find grundleddet: 'Min lillebror elsker pandekager.'","o":["elsker","pandekager","Min lillebror","elsker pandekager"],"a":"Min lillebror","r":"Spørg: Hvem elsker? Svaret 'min lillebror' er grundleddet, og begge ord hører med."},
{"l":3024,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Oliver kom ind i klassen, var alle stille. Der lå en pakke på hans bord, og Ida holdt noget bag ryggen. Han så på tavlen, hvor der stod 11 med store tal. – Nu! hviskede en, og alle begyndte at synge.' Hvad er det, der sker?","o":["Klassen skal have en prøve i matematik","Ida har taget noget fra Olivers bord","Oliver er kommet for sent til timen","Klassen fejrer Olivers fødselsdag"],"a":"Klassen fejrer Olivers fødselsdag","r":"Pakken, tallet 11 og sangen er spor, som tilsammen viser, at han har fødselsdag."},
{"l":3042,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Emma havde lovet at passe naboens kanin i ferien. Den første dag gav hun den mad to gange. Den anden dag glemte hun det, fordi hun var i svømmehallen. Da hun kom hjem, løb hun direkte over til buret med en gulerod.' Hvad fortæller det sidste om Emma?","o":["Hun vil gerne gøre det godt igen","Hun synes, at kaninen er kedelig at passe","Hun skal skynde sig, før naboen kommer hjem","Hun kan bedre lide svømmehallen end kaninen"],"a":"Hun vil gerne gøre det godt igen","r":"Emma har glemt kaninen en hel dag, og nu løber hun direkte over til den med en gulerod. Hun er ked af det, hun glemte."},
{"l":3060,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Noah skulle stå på scenen om ti minutter. Han gentog sin replik igen og igen, men hver gang gik han i stå ved det samme ord. Hans hænder var fugtige. Fru Lund lagde en hånd på hans skulder og sagde: – Du kunne det hele i går.' Hvorfor siger fru Lund det?","o":["Hun vil minde ham om, at prøven var i går","Hun vil give ham mod og ro inden forestillingen","Hun er utilfreds med, at han ikke har øvet mere","Hun vil have ham til at sige replikken til hende"],"a":"Hun vil give ham mod og ro inden forestillingen","r":"Noah er tydeligt nervøs. Fru Lund minder ham om, at han godt kan, for at berolige ham."},
{"l":3080,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form mangler? 'Hun ___ håndbold tre gange om ugen.'","o":["træne","trænner","træner","trænerer"],"a":"træner","r":"Ordet står i nutid og har kun ét n, fordi æ'et er langt."},
{"l":3102,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find biordet i sætningen: 'Min far spiser ikke kød.'","o":["far","spiser","kød","ikke"],"a":"ikke","r":"'Ikke' er et biord, der gør udsagnet benægtende. Det siger noget om hele handlingen."},
{"l":3123,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hjælp! Min grå cykel med kurv forsvandt fra cykelstativet tirsdag eftermiddag. Der sidder en gul refleks på bagskærmen. Hvis du har set den, må du meget gerne sige det til mig i 5.A. Hilsen Mille' Hvilken type tekst er det?","o":["En efterlysning","En anmeldelse","En brugsanvisning","En fagtekst"],"a":"En efterlysning","r":"Mille beskriver det, hun har mistet, og beder andre om at melde sig. Det er en efterlysning."},
{"l":3145,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Selma gemte alle sine mislykkede tegninger i en kasse under sengen. Da hun fyldte tolv, tog hun dem frem og lagde dem på gulvet. Hun kunne se, hvordan stregerne blev sikrere for hvert år. Hun smilede og lagde dem forsigtigt tilbage.' Hvorfor smiler Selma?","o":["Hun synes, at de gamle tegninger er sjove og dumme","Hun kan se, at hun er blevet bedre med årene","Hun har fundet en tegning, hun havde glemt","Hun er glad for at slippe af med tegningerne"],"a":"Hun kan se, at hun er blevet bedre med årene","r":"Hun ser, at stregerne bliver sikrere. Hun passer også på tegningerne, så hun smiler over sin udvikling, ikke for at gøre grin."},
{"l":3163,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kære 6.A. Tak, fordi I viste os rundt på jeres skole i går. Vi er stadig imponeret over jeres robotter. Vi vil gerne invitere jer på besøg hos os i maj, så vi også kan vise jer vores skolehave. Mange hilsner fra 6.B på Toftegårdskolen' Hvad er hovedformålet med brevet?","o":["At bede 6.A om at bygge robotter til dem","At fortælle, hvordan en skolehave passes","At sige tak og invitere 6.A på besøg","At klage over rundvisningen på skolen"],"a":"At sige tak og invitere 6.A på besøg","r":"Brevet indeholder en tak og en invitation. Robotterne og skolehaven er kun detaljer."},
{"l":3182,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan erstatte 'uventet' i sætningen: 'Der kom et uventet besøg i klassen.'","o":["kedeligt","langvarigt","fornemt","overraskende"],"a":"overraskende","r":"Noget uventet har man ikke regnet med, og derfor overrasker det én. Besøget kan godt være både kedeligt og uventet, men det er ikke det samme."},
{"l":3201,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt 'at drikke' i datid: 'Efter kampen ___ holdet en masse vand.'","o":["drak","drikker","drukket","drikke"],"a":"drak","r":"'At drikke' skifter vokal: drikker, drak, har drukket. Datid er 'drak'."},
{"l":3223,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find udråbsordet: 'Hurra, vi har vundet pokalen!'","o":["vundet","Hurra","pokalen","har"],"a":"Hurra","r":"'Hurra' er et udbrud af glæde og står uden for resten af sætningen. Det er et udråbsord."},
{"l":3244,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Viggo kunne ikke sove. Det blæste, og grenen skrabede mod ruden. Han trak dynen op, men så kom han i tanke om, at han selv havde sagt til Sebastian, at han aldrig var bange. Han lagde sig med ryggen til vinduet og knugede sin gamle bamse.' Hvad er forskellen på det, Viggo siger, og det, han gør?","o":["Han siger, at han kan sove, men han ligger vågen","Han siger, at han er for stor til bamser, men knuger en","Han siger, at han aldrig er bange, men det er han","Han siger, at grenen ikke larmer, men det gør den"],"a":"Han siger, at han aldrig er bange, men det er han","r":"Han har pralet over for Sebastian, men dynen og bamsen viser, at han er bange."},
{"l":3262,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I går gik Laura for første gang alene over til sin moster. Det var kun to gader væk, men hun havde aldrig gjort det før. Da hun ringede på, kunne hun høre sit eget hjerte. Mosteren åbnede og sagde: – Så er du blevet stor.' Hvad viser turen om Laura?","o":["At hun er blevet højere, siden mosteren så hende sidst","At hun ikke tør gå nogen steder uden sine forældre","At hun er bange for sin moster","At hun er ved at kunne klare mere selv"],"a":"At hun er ved at kunne klare mere selv","r":"Turen er kort, men Laura har aldrig gået den alene før. Derfor siger mosteren, at hun er blevet stor."},
{"l":3280,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skolens elevråd har talt med ledelsen. Fra næste måned bliver der sat tre nye bænke op ved boldbanen, fordi mange elever savner et sted at sidde. Bænkene er betalt af skolens forældreforening. Elevrådet takker for hjælpen.' Hvem har betalt bænkene?","o":["Forældreforeningen","Elevrådet","Skolens ledelse","Eleverne ved boldbanen"],"a":"Forældreforeningen","r":"Der står, at bænkene er betalt af skolens forældreforening. Elevrådet har kun talt med ledelsen."},
{"l":3300,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Amina kom hjem med karakteren, sagde hendes far ingenting. Han tog bare papiret, læste det to gange og hængte det på køleskabet, helt øverst, hvor alle gæster ville se det.' Hvad viser farens handling?","o":["At han er ligeglad med skolen","At han er stolt af Amina","At han ikke forstår karakteren","At han vil gemme papiret væk"],"a":"At han er stolt af Amina","r":"Han sætter papiret der, hvor alle kan se det. Stoltheden vises gennem handlingen, ikke gennem ord."},
{"l":3321,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler der komma: 'Selvom opgaven var svær gav Liv ikke op.'?","o":["var","gav","svær","Liv"],"a":"svær","r":"Ledsætningen 'Selvom opgaven var svær' står først. Derfor skal der komma efter 'svær'."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
